// api/_lib/wik-brief-logo.js
//
// Base64-embedded copy van img/logo-dark.png voor gebruik in serverless
// functions. Vercel bundelt img/ niet mee in de function-context; via een
// JS-module wordt het logo wél mee-gebundeld op elke deployment.
//
// Bron: img/logo-dark.png (De Forex Opleiding brand-logo, blauw op transparant).
// Ververs door dit script: node -e "require('fs').writeFileSync('api/_lib/wik-brief-logo.js', ...)".
// Of gebruik env-var WIK_LOGO_PATH voor een override op runtime (fs-lookup).
//
// Grootte: 41824 bytes (PNG). Base64-lengte: 55768.

// eslint-disable-next-line max-len
export const WIK_LOGO_BASE64 = '';

/**
 * Buffer-versie van het brand-logo voor pdfkit doc.image().
 * Wordt 1x gedecodeerd bij module-load; hergebruikt op elke request.
 */
export const WIK_LOGO_BUFFER = Buffer.from(WIK_LOGO_BASE64, 'base64');
